<script setup>
import {previewMode} from "../preview/mode"
import SocialLinks from './SocialLinks.vue'
import PrivateContact from './PrivateContact.vue'
import EducationLevelSelect from './EducationLevelSelect.vue'
import LanguageSelect from './LanguageSelect.vue'
const subjects=['Mathematics','Science','English','Sinhala','Tamil','ICT','Business Studies','Accounting','Economics','Biology','Physics','Chemistry','History','Geography','Commerce','Computer Science','Engineering','Art','Music','Law']
function suggestSubject(subject){const parts=form.value.curriculum.split(',').map(s=>s.trim()).filter(Boolean);if(!parts.includes(subject)&&[...parts,subject].join(', ').length<=150)form.value.curriculum=[...parts,subject].join(', ')}
import SocialIcon from './SocialIcon.vue'
import {socialNetworks} from './socials.js'
import {ref} from 'vue'
import {isDemo,call,uploadImage} from '../service'
import {community,createProfile} from './community'
import {safeLink} from '../rules'
const props=defineProps({member:Object}),emit=defineEmits(['saved','navigate'])
const error=ref(''),busy=ref(false),existing=ref(null)
const form=ref({username:'',display_name:props.member.full_name,kind:props.member.role==='Admin'?'Institute':props.member.role==='Student'?'Student':'Teacher',country:'Sri Lanka',bio:'',tagline:'',qualifications:'',curriculum:'',grades:'',languages:'English',socials:{facebook:'',instagram:'',twitter:'',youtube:'',linkedin:'',tiktok:''},is_school:false})
async function load(){try{const d=isDemo?[...community().profiles,...community().pending].find(p=>p.user===props.member.name):(await call('me',{},'profiles')).profile;if(d){existing.value=d;Object.assign(form.value,d);if(typeof d.socials==='string')form.value.socials=JSON.parse(d.socials)}}catch(e){error.value=e.message}}
async function save(){busy.value=true;error.value='';try{if(form.value.kind==='Student')form.value.socials={};for(const url of Object.values(form.value.socials||{}))if(url&&!safeLink(url))throw Error('Use a valid HTTPS social link.');if(isDemo)createProfile({...form.value,user:props.member.name});else await call('save_profile',{data:form.value},'profiles');emit('saved')}catch(e){error.value=e.message}finally{busy.value=false}}
async function imageUpload(event,kind){const file=event.target.files[0];if(!file)return;busy.value=true;error.value='';try{if(file.size>5*1024*1024)throw Error('Choose an image no larger than 5 MB.');if(previewMode){form.value[kind]=await uploadImage(file);return;}const body=new FormData();body.append('kind',kind);body.append('file',file);const r=await fetch('/api/method/institute_lms.profiles.upload_image',{method:'POST',credentials:'same-origin',headers:{'X-Frappe-CSRF-Token':window.csrf_token||''},body});if(!r.ok)throw Error('Image upload failed. Save your profile first, then use JPEG, PNG or WebP.');const d=await r.json();form.value[kind]=d.message.url}catch(e){error.value=e.message}finally{busy.value=false}}
load()
</script>
<template><form class="panel public-profile-editor" @submit.prevent="save"><div class="profile-cover-preview"><img v-if="form.cover_image" :src="form.cover_image" alt="Your profile cover"><div class="profile-photo-preview"><img v-if="form.profile_image" :src="form.profile_image" alt="Your profile picture"><span v-else>{{form.display_name?.slice(0,1)}}</span></div></div><SocialLinks :profile="form"/><h2>A profile that feels like you.</h2><button v-if="member.role==='Teacher'" type="button" class="button subtle" @click="emit('navigate','papers')">My papers & assessments →</button><template v-if="existing"><label>Cover photo · 8:3 · up to 5 MB<input type="file" accept="image/jpeg,image/png,image/webp" :disabled="busy" @change="imageUpload($event,'cover_image')"></label><label>Profile photo · square · up to 5 MB<input type="file" accept="image/jpeg,image/png,image/webp" :disabled="busy" @change="imageUpload($event,'profile_image')"></label><p>Images are centre-cropped and compressed. They are visible to people viewing your public profile.</p></template><p>Your username stays yours. Changes to your name, country or account identity need review. You can update your bio anytime.<span v-if="form.kind!=='Student'"> Your social links appear on your public profile.</span></p><p v-if="error" role="alert">{{error}}</p><label>Display name<input v-model="form.display_name" required maxlength="120"></label><label>Tagline<input v-model="form.tagline" maxlength="120" placeholder="For better education for all"></label><label v-if="form.kind==='Teacher'">Qualifications<input v-model="form.qualifications" maxlength="240" placeholder="BSc, BEd, MSc…"></label><label>Unique username<input v-model="form.username" :readonly="!!existing" required pattern="[a-z][a-z0-9_]{2,29}" maxlength="30"></label><label>Country<input v-model="form.country" required maxlength="80"></label><label>About you<textarea v-model="form.bio" maxlength="1000"></textarea></label><template v-if="form.kind!=='Student'"><label>Curriculum / subjects<input v-model="form.curriculum" maxlength="150" list="profile-subjects" placeholder="Type a subject or choose a suggestion"></label><datalist id="profile-subjects"><option v-for="subject in subjects" :value="subject"/></datalist><div class="subject-suggestions" aria-label="Suggested subjects"><button v-for="subject in subjects.slice(0,10)" type="button" class="button subtle small" @click="suggestSubject(subject)">{{subject}} +</button></div><p>Choose several subjects, separated by commas. You can add your own.</p></template><EducationLevelSelect v-model="form.grades"/><LanguageSelect v-model="form.languages"/><section v-if="form.kind==='Teacher'||form.kind==='Institute'" class="provider-social-editor"><h3>Find you beyond the classroom.</h3><p>Add your official social profiles. All six icons appear on your profile. Add a link to make its icon clickable.</p><label v-for="(name,key) in socialNetworks" :key="key"><span class="social-field-name"><SocialIcon :network="key"/>{{name}}</span><input v-model="form.socials[key]" type="url" maxlength="500" placeholder="https://…"></label></section><label v-if="form.kind==='Institute'" class="checkbox-label"><input v-model="form.is_school" type="checkbox">School workspace · platform billing only, no student class checkout</label><button class="button primary" :disabled="busy">Save profile</button></form><PrivateContact :member="member"/></template>
<style>.public-profile-editor{padding:30px;margin:24px 0;max-width:760px}.public-profile-editor label{display:flex;flex-direction:column;gap:10px;margin:18px 0;font-size:12px}.public-profile-editor :is(input,textarea){padding:13px;background:var(--student-card);color:var(--student-ink);border:1px solid var(--student-border);border-radius:12px}.public-profile-editor .checkbox-label{flex-direction:row}.public-profile-editor p{margin:15px 0;font-size:12px}</style>

<style>.profile-cover-preview{position:relative;aspect-ratio:8/3;background:linear-gradient(125deg,#e3d6f5,#cebdde);border-radius:18px;margin-bottom:68px}.profile-cover-preview>img{width:100%;height:100%;object-fit:cover;border-radius:18px}.profile-photo-preview{width:104px;height:104px;border:5px solid var(--student-card,#fff);border-radius:50%;position:absolute;bottom:-40px;left:25px;background:#ad90c8;display:grid;place-items:center;font-size:35px;color:white;overflow:hidden}.profile-photo-preview img{width:100%;height:100%;object-fit:cover}</style>

<style>.provider-social-editor{border-top:1px solid var(--student-border);padding-top:24px;margin-top:24px}.public-profile-editor .social-field-name{display:flex;align-items:center;gap:10px}.social-field-name svg{width:19px;height:19px;flex-shrink:0}.public-profile-editor>.provider-social-links{justify-content:flex-end;margin-top:-48px;margin-bottom:30px}</style>
<style>.subject-suggestions{display:flex;flex-wrap:wrap;gap:8px}.subject-suggestions button{font-size:11px}</style>
